 Promise.all([json('data/catalog.json'),json('data/sources.json'),languageReady]).then(([c,s])=>{catalog=c;countries=c.countries;C=Object.fromEntries(countries.map(x=>[x.code,x]));sources=s;sourceById=Object.fromEntries(s.filter(x=>x.id).map(x=>[x.id,x]));if(!R[state.region])state.region='all';if(state.country&&!C[state.country])state.country='TR';if(state.country&&state.region!=='all'&&!catalog.regions[state.region]?.includes(state.country))state.region='all';initialized=true;return enqueueRender(false);}).catch(error=>{console.error(error);app.innerHTML=`<div class="content-wrap"><div class="data-error">${e(t('Could not load data. Please retry.'))}</div></div>`;app.setAttribute('aria-busy','false');});
 window.SamaAtlas={get state(){return {...state};},get records(){return records;},get filtered(){return filtered;},get catalog(){return catalog;},get map(){return map;},selectRecord};
